      "supported_python_versions": ["3.9", "3.10", "3.11", "3.12"]
    },
    "pytest_ini": {
      "test_paths": ["tests/basic", "tests/help", "tests/browser", "tests/scrape"],
      "default_options": "-p no:warnings",
      "test_command": "pytest"
    },
